/* Krishi Setu — GitHub-ready, double-click friendly edition.
   Frontend-only application: no server, npm, database install, or build step.
   Persistent demo data lives in localStorage and is isolated by account id.
*/
'use strict';

const KEY={users:'ks_users_v5',session:'ks_session_v5',listings:'ks_listings_v5',orders:'ks_orders_v5',tickets:'ks_tickets_v5',saved:'ks_saved_v5'};
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:0});
const qty=v=>Number(v||0).toLocaleString('en-IN')+' kg';
const uid=()=>crypto.randomUUID?crypto.randomUUID():'ks-'+Date.now().toString(36)+Math.random().toString(36).slice(2,9);
const route=()=>location.hash.replace(/^#/,'').split('?')[0]||'home';
const query=()=>new URLSearchParams(location.hash.includes('?')?location.hash.split('?').slice(1).join('?'):'');
const read=(k,f)=>{try{const v=JSON.parse(localStorage.getItem(k));return v??f}catch{return f}};
const write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const currentUser=()=>{const id=localStorage.getItem(KEY.session);return read(KEY.users,[]).find(u=>u.id===id)||null};
const isIn=()=>Boolean(currentUser());
const state={user:null,listings:[],orders:[],saved:[],forecast:'tomatoes',forecastTick:0,marketFilter:{q:'',category:'',location:'',sort:'recommended'}};

const crops=[
 {id:'tomatoes',name:'Tomatoes',icon:'🍅',tone:'tomato',grade:'Grade A',price:24,quantityKg:5200,location:'Nashik, Maharashtra',farmer:'Patil Farms',baseTrend:12,season:'Strong'},
 {id:'onions',name:'Onions',icon:'🧅',tone:'onion',grade:'Grade A',price:18,quantityKg:10400,location:'Lasalgaon, Maharashtra',farmer:'Deshmukh Agro',baseTrend:15,season:'Very strong'},
 {id:'potatoes',name:'Potatoes',icon:'🥔',tone:'potato',grade:'Grade A',price:20,quantityKg:8300,location:'Agra, Uttar Pradesh',farmer:'Sharma Farmers Co.',baseTrend:7,season:'Rising'},
 {id:'rice',name:'Rice (Grade A)',icon:'🌾',tone:'rice',grade:'Grade A',price:32,quantityKg:20400,location:'Karnal, Haryana',farmer:'Singh Agro',baseTrend:9,season:'Rising'},
 {id:'mangoes',name:'Mangoes',icon:'🥭',tone:'mango',grade:'Export',price:40,quantityKg:2100,location:'Ratnagiri, Maharashtra',farmer:'Konkan Growers',baseTrend:5,season:'Steady'},
 {id:'wheat',name:'Wheat',icon:'🌿',tone:'wheat',grade:'Premium',price:28,quantityKg:8200,location:'Nashik, Maharashtra',farmer:'Green Harvest',baseTrend:8,season:'Rising'}
];
const seedListings=()=>crops.map((p,i)=>({...p,id:'seed-'+p.id,farmerId:'public-'+i,isSeed:true,createdAt:'2026-09-01T08:00:00Z'}));

const demoUsers=[
 {id:'demo-farmer',name:'Demo Farmer',email:'farmer@krishisetu.demo',location:'Nashik, Maharashtra',role:'farmer',passwordHash:'26c07fc7be1668f8ea7e3801d4ffdbf33de487a593a69028936ec49f2c89f6ab',createdAt:'2026-09-01T08:00:00Z'},
 {id:'demo-buyer',name:'Demo Bulk Buyer',email:'buyer@krishisetu.demo',location:'Mumbai, Maharashtra',role:'buyer',passwordHash:'e547bd13228250dfb4c7df1d1ebb78cfd9f2ada56ebb0c425d35829dd3ac4ae8',createdAt:'2026-09-01T08:00:00Z'}
];
function bootstrap(){
 const users=read(KEY.users,[]);
 demoUsers.forEach(d=>{const i=users.findIndex(u=>u.email===d.email);if(i===-1)users.push(d);else users[i]={...users[i],...d}});
 write(KEY.users,users);
 if(!localStorage.getItem(KEY.orders))write(KEY.orders,[]);
 if(!localStorage.getItem(KEY.tickets))write(KEY.tickets,[]);
 if(!localStorage.getItem(KEY.listings))write(KEY.listings,seedListings());
 state.user=currentUser();state.listings=read(KEY.listings,seedListings());state.orders=read(KEY.orders,[]);state.saved=state.user?read(KEY.saved+'_'+state.user.id,[]):[];
}
function saveState(){write(KEY.listings,state.listings);write(KEY.orders,state.orders);if(state.user)write(KEY.saved+'_'+state.user.id,state.saved)}
function toast(msg,type=''){const el=$('#toast');el.textContent=msg;el.className='toast show '+type;clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.className='toast',3200)}
function go(h){location.hash=h}
function brand(){return `<a class="brand" href="#home"><img class="brand-mark" src="assets/krishi-setu-mark.webp" alt="Krishi Setu"><span class="brand-copy"><span class="brand-krishi">Krishi</span><span class="brand-setu">Setu</span></span></a>`}
function publicHeader(active=''){return `<header class="public-header"><div class="container nav">${brand()}<nav class="nav-links"><a class="${active==='home'?'active':''}" href="#home">Home</a><a class="${active==='marketplace'?'active':''}" href="#marketplace">Marketplace</a><a class="${active==='how'?'active':''}" href="#how">How It Works</a><a class="${active==='ai'?'active ai-nav':'ai-nav'}" href="#ai">✦ AI Forecast</a><a class="${active==='track'?'active':''}" href="#track">Track Order</a><a class="${active==='support'?'active':''}" href="#support">Support</a></nav><div class="nav-actions"><a class="btn outline small" href="#${isIn()?'dashboard':'login'}">${isIn()?'Dashboard':'Login'}</a><a class="btn small" href="#${isIn()?'dashboard/profile':'register'}">${isIn()?'Account':'Register'}</a></div><button class="icon-btn mobile-menu" data-menu aria-label="Open menu">☰</button></div><div class="mobile-drawer" data-drawer>${brand()}<a href="#home">Home</a><a href="#marketplace">Marketplace</a><a href="#how">How It Works</a><a class="ai-nav" href="#ai">✦ AI Forecast</a><a href="#track">Track Order</a><a href="#support">Support</a><div class="mobile-drawer-actions"><a class="btn outline" href="#${isIn()?'dashboard':'login'}">${isIn()?'Dashboard':'Login'}</a><a class="btn" href="#${isIn()?'dashboard/profile':'register'}">${isIn()?'Account':'Register'}</a></div></div></header>`}
function footer(){return `<footer class="public-footer"><div class="container footer-grid"><div>${brand()}<p>Connecting India's farmers and businesses through transparent agricultural trade and better demand visibility.</p></div><div><h4>Platform</h4><a href="#marketplace">Marketplace</a><a href="#ai">AI Forecast</a><a href="#track">Track Order</a></div><div><h4>Workflows</h4><a href="#register">For Farmers</a><a href="#register">For Bulk Buyers</a><a href="#how">How It Works</a></div><div><h4>Help</h4><a href="#support">Support</a><a href="#login">Login</a><a href="#register">Register</a></div></div><div class="container footer-bottom"><span>© 2026 Krishi Setu</span><span>Better markets. Brighter tomorrows.</span></div></footer>`}
function visual(p){return `<div class="produce-visual ${esc(p.tone||'leaf')}"><span class="crop-symbol ${esc(p.tone||'leaf')}"></span><span class="produce-name">${esc(p.name)}</span><span class="produce-grade">${esc(p.grade||'Fresh')}</span></div>`}
function liveTrend(p){const n=(Number(p.baseTrend??p.trend??7)+Math.round(Math.sin(Date.now()/5200+(p.id||'').length)*1.4));return Math.max(2,Math.min(24,n))}
function forecastPill(p){const t=liveTrend(p);return `<div class="forecast-pill"><span>✦</span><b>${t>=12?'High demand':t>=8?'Rising demand':'Positive outlook'}</b><strong>+${t}%</strong><small>next 7 days</small></div>`}
function ticker(){const arr=crops.map(p=>`${p.name} <b>↑ ${liveTrend(p)}%</b>`).join('');return `<div class="demand-ticker"><div class="demand-ticker-label">✦ LIVE AI DEMAND SIGNAL</div><div class="demand-window"><div class="demand-track">${arr}${arr}</div></div><a href="#ai">See forecast →</a></div>`}
function card(p){const saved=state.saved.includes(p.id);return `<article class="product-card"><div class="product-photo">${visual(p)}</div><div class="product-body"><div class="product-heading"><h3>${esc(p.name)}</h3><button class="save-btn ${saved?'saved':''}" data-save="${esc(p.id)}" aria-label="Save ${esc(p.name)}">${saved?'♥':'♡'}</button></div><div class="price">${money(p.price)}<span>/kg</span></div><div class="product-meta">Available: ${qty(p.quantityKg)}<br>⌖ ${esc(p.location)}<br>♙ ${esc(p.farmer)}</div>${forecastPill(p)}<div class="product-actions"><a class="btn outline" href="#product/${encodeURIComponent(p.id)}">Details</a>${state.user?.role==='buyer'?`<button class="btn" data-order="${esc(p.id)}">Buy</button>`:`<button class="btn outline" data-save="${esc(p.id)}">${saved?'Saved ✓':'Save'}</button>`}</div></div></article>`}

function home(){return `${publicHeader('home')}<main class="route-enter"><section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow">A stronger tomorrow together</div><h1>Connecting Farmers<br>to a <span>Larger Tomorrow</span></h1><p>Krishi Setu brings farmers and bulk buyers together with transparent trade, live logistics and demand intelligence that updates as the market moves.</p><div class="hero-actions"><a class="btn" href="#marketplace">Explore Marketplace →</a><a class="btn outline" href="#how">▶ How it works</a></div><div class="trust-row"><span>Direct market access</span><span>Better prices</span><span>Verified supply</span><span>AI-powered decisions</span></div><a class="hero-ai-card" href="#ai"><span class="ai-pulse">✦</span><span><b>AI Demand Forecasting</b><small>Live signals, projected demand and recommended actions — built into the buying and selling journey.</small></span><strong>Explore →</strong></a></div></div><div class="container"><div class="hero-stat"><div><b>5,000+</b><small>Farmers</small></div><div><b>1,200+</b><small>Bulk Buyers</small></div><div><b>20,000+</b><small>Tons Traded</small></div><div><b>28</b><small>States Covered</small></div></div></div></section>${ticker()}<section class="feature-strip"><div class="container feature-grid"><article class="feature-tile"><span class="tile-icon">⌁</span><div><b>For Farmers</b><p>Reach buyers and see future demand before listing.</p></div></article><article class="feature-tile"><span class="tile-icon">▦</span><div><b>For Bulk Buyers</b><p>Source verified produce with clear supply signals.</p></div></article><article class="feature-tile"><span class="tile-icon">▰</span><div><b>Integrated Logistics</b><p>Follow every shipment from pickup to delivery.</p></div></article><article class="feature-tile ai-feature"><span class="tile-icon">✦</span><div><b>AI Demand Forecast</b><p>Turn demand movement into a buying or selling decision.</p></div></article></div></section><section class="section"><div class="container story-grid"><div><div class="eyebrow">Fresher supply chains</div><h2>From fields to opportunities.</h2><p>Instead of making farmers and buyers guess what comes next, Krishi Setu puts demand movement beside the decision: list, source, order and track from one connected workspace.</p><div class="hero-actions"><a class="btn" href="#register">Create your workspace</a><a class="btn outline" href="#ai">See AI forecast</a></div></div><div class="story-media"><div class="farm-art"><span class="floating-chip chip1">🌱 Supply ready</span><span class="floating-chip chip2">✦ Demand +12%</span></div><div class="market-art"><span class="floating-chip chip1">₹ Better access</span><span class="floating-chip chip2">🚚 Tracked delivery</span></div></div></div></section><section class="section soft" id="how"><div class="container"><div class="section-head"><div><div class="eyebrow">How it works</div><h2>One connected agricultural journey.</h2></div><p>Three simple steps for farmers and bulk buyers — with demand intelligence running underneath.</p></div><div class="simple-cards"><article class="simple-card"><span class="number">01</span><h3>Discover</h3><p>Browse verified produce and see live AI demand signals before committing.</p></article><article class="simple-card"><span class="number">02</span><h3>Trade</h3><p>Farmers publish supply. Buyers place quantities and delivery requirements.</p></article><article class="simple-card"><span class="number">03</span><h3>Track</h3><p>Every order receives a unique tracking code and a private logistics timeline.</p></article></div></div></section></main>${footer()}`}

function marketplace(){return `${publicHeader('marketplace')}<main class="page route-enter"><div class="container"><div class="page-top"><div><div class="eyebrow">Direct agricultural trade</div><h1>Marketplace</h1><p>Browse produce with an AI demand signal built into every listing.</p></div>${isIn()?`<a class="btn" href="#dashboard">Open workspace →</a>`:`<a class="btn outline" href="#register">Join to buy or sell</a>`}</div>${ticker()}<div class="filters"><input id="market-search" class="input" value="${esc(state.marketFilter.q)}" placeholder="Search produce, farmer or location"><select id="market-category" class="select"><option value="">All produce</option>${crops.map(p=>`<option ${state.marketFilter.category===p.name?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="market-location" class="select"><option value="">All locations</option><option ${state.marketFilter.location==='Maharashtra'?'selected':''}>Maharashtra</option><option ${state.marketFilter.location==='Uttar Pradesh'?'selected':''}>Uttar Pradesh</option><option ${state.marketFilter.location==='Haryana'?'selected':''}>Haryana</option></select><select id="market-sort" class="select"><option value="recommended" ${state.marketFilter.sort==='recommended'?'selected':''}>Recommended</option><option value="low" ${state.marketFilter.sort==='low'?'selected':''}>Price: Low to High</option><option value="high" ${state.marketFilter.sort==='high'?'selected':''}>Price: High to Low</option><option value="demand" ${state.marketFilter.sort==='demand'?'selected':''}>Highest AI demand</option></select></div><div id="market-grid" class="product-grid">${filteredListings().map(card).join('')||`<div class="panel empty" style="grid-column:1/-1"><span class="empty-icon">⌁</span><h3>No matching produce</h3><p>Try a different crop, location or search term.</p><button class="btn outline" data-clear-filters>Clear filters</button></div>`}</div></div></main>${footer()}`}
function filteredListings(){let a=[...state.listings];const f=state.marketFilter;const q=f.q.toLowerCase();if(q)a=a.filter(p=>[p.name,p.farmer,p.location].join(' ').toLowerCase().includes(q));if(f.category)a=a.filter(p=>p.name===f.category);if(f.location)a=a.filter(p=>p.location.includes(f.location));if(f.sort==='low')a.sort((x,y)=>x.price-y.price);if(f.sort==='high')a.sort((x,y)=>y.price-x.price);if(f.sort==='demand')a.sort((x,y)=>liveTrend(y)-liveTrend(x));if(f.sort==='recommended')a.sort((x,y)=>liveTrend(y)-liveTrend(x));return a}
function productDetail(id){const p=state.listings.find(x=>x.id===id);if(!p)return notFound();return `${publicHeader('marketplace')}<main class="page route-enter"><div class="container"><a class="back-link" href="#marketplace">← Back to marketplace</a><section class="detail-card"><div class="detail-photo">${visual(p)}</div><div class="detail-info"><div class="eyebrow">${esc(p.grade)} · ${p.isSeed?'verified supply':'farmer listing'}</div><h1>${esc(p.name)}</h1><p class="lead">${esc(p.farmer)} · ${esc(p.location)}</p><div class="detail-price">${money(p.price)} <small>/kg</small></div>${forecastPill(p)}<div class="detail-stat-grid"><div><small>Available</small><b>${qty(p.quantityKg)}</b></div><div><small>7-day demand</small><b class="green">+${liveTrend(p)}%</b></div></div><div class="notice">✦ <b>AI decision signal:</b> demand is ${liveTrend(p)>=12?'strong and accelerating':liveTrend(p)>=8?'rising steadily':'positive'} for the next 7 days. ${state.user?.role==='farmer'?'Consider listing while the signal is favorable.':'Consider locking supply before demand tightens.'}</div><div class="detail-actions">${state.user?.role==='buyer'?`<button class="btn" data-order="${esc(p.id)}">Order this produce</button>`:`<a class="btn" href="#register">Register to order</a>`}<button class="btn outline" data-save="${esc(p.id)}">${state.saved.includes(p.id)?'Saved ✓':'Save listing'}</button></div></div></section></div></main>${footer()}`}

function authPage(kind){const login=kind==='login';return `${publicHeader()}<main class="auth-page route-enter"><div class="container auth-grid"><section class="auth-art"><div class="auth-art-content"><div><div class="eyebrow" style="color:#a9e7bf">Krishi Setu intelligence</div><h2>${login?'Welcome back.':'Build your farm-to-market workspace.'}</h2><p>${login?'Your private orders, listings, logistics and AI signals are waiting.':'Choose your role, create an account and start trading with demand visibility from day one.'}</p></div>${login?`<div class="demo-access demo-access-left"><b>Demo accounts</b><div><span>🌱 Farmer</span><code>farmer@krishisetu.demo</code><code>farmer123</code></div><div><span>🏢 Bulk Buyer</span><code>buyer@krishisetu.demo</code><code>buyer123</code></div></div>`:''}<div class="auth-live"><div class="auth-live-card"><span class="ai-pulse">✦</span><span><b>AI demand is live</b><small>Onions +${liveTrend(crops[1])}% · Tomatoes +${liveTrend(crops[0])}%</small></span></div><div class="auth-live-card"><span>🚚</span><span><b>Private logistics</b><small>Only orders belonging to your account appear.</small></span></div></div></div></section><section class="auth-form-card"><div class="eyebrow">Krishi Setu account</div><h1>${login?'Welcome back':'Create your workspace'}</h1><p>${login?'Sign in to your private farmer or bulk buyer workspace.':'Start buying smarter or selling with better demand visibility.'}</p>${!login?`<div class="role-switch"><button type="button" class="active" data-role="farmer">🌱 Farmer</button><button type="button" data-role="buyer">🏢 Bulk Buyer</button></div>`:''}<form id="auth-form" data-kind="${login?'login':'register'}">${login?'':`<div class="field"><label for="auth-name">Full name</label><input id="auth-name" class="input" required name="name" placeholder="e.g. Arjun Patel" autocomplete="name"></div>`}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" class="input" required type="email" name="email" placeholder="you@example.com" autocomplete="email"></div><div class="field"><label for="auth-password">Password</label><div class="password-wrap"><input id="auth-password" class="input" required minlength="6" type="password" name="password" placeholder="At least 6 characters" autocomplete="${login?'current-password':'new-password'}"><button type="button" class="password-toggle" data-password-toggle>Show</button></div></div>${login?'':`<div class="field"><label for="auth-location">Location</label><input id="auth-location" class="input" required name="location" placeholder="City, State" autocomplete="address-level2"></div>`}<button class="btn full" type="submit">${login?'Sign in securely →':'Create my workspace →'}</button><div id="auth-error" class="form-error" aria-live="polite"></div></form><p class="auth-bottom">${login?'New to Krishi Setu?':'Already have an account?'} <a href="#${login?'register':'login'}">${login?'Create an account':'Sign in'}</a></p></section></div></main>${footer()}`}

function dashboardShell(active,content){const u=state.user;const links=[['dashboard','⌂','Overview'],['dashboard/orders','▣','Orders'],['dashboard/listings','⌁','My Listings'],['dashboard/ai','✦','AI Insights'],['dashboard/logistics','▰','Logistics & Tracking'],['dashboard/support','?','Support'],['dashboard/profile','●','Profile']];return `<div class="app-shell route-enter"><header class="app-topbar">${brand()}<span class="role-chip">${u.role==='farmer'?'🌱 Farmer workspace':'🏢 Bulk buyer workspace'}</span><div class="app-topbar-spacer"></div><div class="app-user"><span class="avatar">${esc((u.name||'U')[0].toUpperCase())}</span><span class="user-name"><b>${esc(u.name)}</b></span></div><button class="icon-btn dashboard-menu-btn" data-dash-menu aria-label="Toggle dashboard sidebar" aria-expanded="true">☰</button></header><div class="app-body"><aside class="sidebar" data-sidebar><div class="side-section">Workspace</div>${links.map(x=>`<a class="side-link ${active===x[0]?'active':''}" href="#${x[0]}"><span>${x[1]}</span>${x[2]}</a>`).join('')}<div class="side-bottom"><button class="btn outline full" data-logout>Sign out</button></div></aside><main class="app-main">${content}</main></div></div>`}
function dashboard(){const u=state.user;const mine=state.orders.filter(o=>u.role==='buyer'?o.buyerId===u.id:o.farmerId===u.id);const myListings=state.listings.filter(p=>p.farmerId===u.id);return dashboardShell('dashboard',`<div class="subpage-title"><div><div class="eyebrow">Private workspace</div><h1>Good to see you, ${esc(u.name.split(' ')[0])}.</h1><p>Your account starts clean. Only your own listings, orders and logistics are shown.</p></div><a class="btn" href="#${u.role==='farmer'?'dashboard/listings':'marketplace'}">${u.role==='farmer'?'Create listing':'Find produce'} →</a></div><div class="metric-grid"><div class="metric"><span class="metric-icon">⌁</span><div><b>${u.role==='farmer'?myListings.length:mine.length}</b><small>${u.role==='farmer'?'Your listings':'Your orders'}</small><em>Private account data</em></div></div><div class="metric"><span class="metric-icon">▰</span><div><b>${mine.filter(o=>o.status!=='Delivered').length}</b><small>Active logistics</small><em>Only your shipments</em></div></div><div class="metric"><span class="metric-icon">✦</span><div><b>+${Math.max(...crops.map(liveTrend))}%</b><small>Top demand signal</small><em>Live AI forecast</em></div></div><div class="metric"><span class="metric-icon">₹</span><div><b>${money(mine.reduce((s,o)=>s+o.total,0))}</b><small>${u.role==='farmer'?'Order value':'Procurement value'}</small><em>From your account</em></div></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="eyebrow">AI decision support</div><h2>What may move next</h2></div><a href="#dashboard/ai">Open AI Insights →</a></div><div class="ai-dashboard-card"><div><span class="ai-pulse">✦</span><h3>${topCrop().name} demand is leading</h3><p>Current forecast: <b>+${liveTrend(topCrop())}%</b> expected demand over the next 7 days.</p></div><a class="btn" href="#dashboard/ai">Explore forecast</a></div></section><section class="panel"><div class="panel-head"><div><div class="eyebrow">Account activity</div><h2>Recent orders</h2></div><a href="#dashboard/orders">View all →</a></div>${mine.length?mine.slice(0,4).map(orderRow).join(''):`<div class="empty"><span class="empty-icon">▱</span><h3>No orders yet</h3><p>This is a clean account. Orders will appear here after a purchase or when a buyer orders one of your listings.</p></div>`}</section></div>`)}
function topCrop(){return [...crops].sort((a,b)=>liveTrend(b)-liveTrend(a))[0]}
function orderRow(o){return `<div class="order-row"><div><b>${esc(o.orderCode)}</b><small>${esc(o.crop)}</small></div><div><b>${qty(o.quantityKg)}</b><small>${money(o.total)}</small></div><div><span class="status">${esc(o.status)}</span></div><div><a href="#dashboard/logistics?track=${encodeURIComponent(o.trackingId)}">Track →</a></div></div>`}
function ordersPage(){const mine=state.orders.filter(o=>state.user.role==='buyer'?o.buyerId===state.user.id:o.farmerId===state.user.id);return dashboardShell('dashboard/orders',`<div class="subpage-title"><div><div class="eyebrow">Private account data</div><h1>${state.user.role==='farmer'?'Orders from buyers':'My orders'}</h1><p>Only orders connected to <b>${esc(state.user.email)}</b> are shown.</p></div></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Produce</th><th>Quantity</th><th>Counterparty</th><th>Status</th><th>Tracking</th></tr></thead><tbody>${mine.length?mine.map(o=>`<tr><td><b>${esc(o.orderCode)}</b><br><small>${esc(o.createdAt.slice(0,10))}</small></td><td>${esc(o.crop)}</td><td>${qty(o.quantityKg)}</td><td>${esc(state.user.role==='farmer'?o.buyerName:o.farmerName)}</td><td><span class="status">${esc(o.status)}</span></td><td><a href="#dashboard/logistics?track=${encodeURIComponent(o.trackingId)}">${esc(o.trackingId)}</a></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty"><span class="empty-icon">▱</span><h3>No orders yet</h3><p>No order from another account can appear here.</p></div></td></tr>`}</tbody></table></div></section>`)}
function logisticsPage(){const mine=state.orders.filter(o=>state.user.role==='buyer'?o.buyerId===state.user.id:o.farmerId===state.user.id);const selected=query().get('track');return dashboardShell('dashboard/logistics',`<div class="subpage-title"><div><div class="eyebrow">Private logistics</div><h1>Logistics & Tracking</h1><p>Only shipments belonging to this account appear here. A new account has an empty state.</p></div><a class="btn outline" href="#track">Public tracking →</a></div>${mine.length?mine.map(o=>`<section class="panel tracking-card ${selected===o.trackingId?'selected-tracking':''}"><div class="tracking-head"><div><div class="eyebrow">${esc(o.trackingId)}</div><h2>${esc(o.crop)} · ${qty(o.quantityKg)}</h2><p>${esc(o.destination)}</p></div><div style="display:grid;gap:9px;justify-items:end"><span class="status">${esc(o.status)}</span>${state.user.role==='farmer'&&o.status!=='Delivered'?`<button class="btn small" data-advance-order="${esc(o.id)}">Advance shipment →</button>`:''}</div></div><div class="timeline">${o.events.map(e=>`<div class="timeline-step ${e.done?'done':''}"><span>${e.done?'✓':'○'}</span><b>${esc(e.label)}</b><small>${esc(e.date||'Pending')}</small></div>`).join('')}</div></section>`).join(''):`<section class="panel empty" style="padding:90px 20px"><span class="empty-icon">▰</span><h2>No shipments yet</h2><p>There is no logistics data on this account. Your first order will create a private tracking timeline here.</p><a class="btn" href="#${state.user.role==='buyer'?'marketplace':'dashboard/listings'}">${state.user.role==='buyer'?'Browse marketplace':'Create a listing'} →</a></section>`}`)}
function advanceOrder(id){const orders=read(KEY.orders,[]);const o=orders.find(x=>x.id===id&&x.farmerId===state.user.id);if(!o)return;const next=['Order placed','Confirmed','Picked up','In transit','Delivered'];const idx=next.indexOf(o.status);const ni=Math.min(next.length-1,idx+1);o.status=next[ni];o.events.forEach((e,i)=>{e.done=i<=ni;e.date=i<=ni?(e.date||new Date().toLocaleDateString('en-IN')):''});write(KEY.orders,orders);state.orders=orders;toast(ni===4?'Shipment marked delivered.':'Shipment advanced to '+o.status+'.');render()}
function listingsPage(){if(state.user.role!=='farmer')return dashboardShell('dashboard/listings',`<div class="subpage-title"><div><div class="eyebrow">Buyer workspace</div><h1>Saved & sourcing</h1><p>Use the marketplace to find supply and build your procurement flow.</p></div><a class="btn" href="#marketplace">Open marketplace →</a></div><section class="panel"><h2>Saved listings</h2>${state.saved.length?`<div class="listing-grid">${state.saved.map(id=>state.listings.find(p=>p.id===id)).filter(Boolean).map(p=>listingRow(p)).join('')}</div>`:`<div class="empty"><span class="empty-icon">♡</span><h3>No saved listings</h3><p>Save marketplace produce to build a sourcing shortlist.</p><a class="btn outline" href="#marketplace">Browse produce</a></div>`}</section>`);const mine=state.listings.filter(p=>p.farmerId===state.user.id);return dashboardShell('dashboard/listings',`<div class="subpage-title"><div><div class="eyebrow">Farmer workspace</div><h1>My listings</h1><p>Publish supply and use the live demand signal to decide what to list next.</p></div><button class="btn" data-new-listing>+ Create listing</button></div><div class="notice" style="margin-bottom:18px">✦ <b>AI recommendation:</b> ${topCrop().name} is currently showing the strongest demand signal at +${liveTrend(topCrop())}%. ${mine.length?'Your listings are being evaluated against this live signal.':'Create your first listing to start selling.'}</div><section class="panel">${mine.length?`<div class="listing-grid">${mine.map(listingRow).join('')}</div>`:`<div class="empty"><span class="empty-icon">⌁</span><h2>No listings yet</h2><p>Your marketplace inventory is empty. Create a listing and it will immediately appear in the marketplace on this browser.</p><button class="btn" data-new-listing>Create your first listing →</button></div>`}</section>`)}
function listingRow(p){return `<div class="listing-row"><div class="listing-visual">${visual(p)}</div><div><h3>${esc(p.name)}</h3><p>${money(p.price)}/kg · ${qty(p.quantityKg)} · ${esc(p.location)}</p><div class="forecast-inline">✦ AI demand <b>+${liveTrend(p)}%</b> next 7 days</div></div><div class="listing-actions"><a class="btn outline" href="#product/${encodeURIComponent(p.id)}">View</a>${state.user.role==='farmer'&&p.farmerId===state.user.id?`<button class="btn outline" data-delete-listing="${esc(p.id)}">Remove</button>`:`<button class="btn" data-order="${esc(p.id)}">Order</button>`}</div></div>`}
function aiPage(privatePage=false){return privatePage?dashboardShell('dashboard/ai',aiContent(true)):`${publicHeader('ai')}<main class="page route-enter"><div class="container">${aiContent(false)}</div></main>${footer()}`}
function aiContent(privatePage){return `<section class="ai-hero"><div><div class="eyebrow">Krishi Setu Intelligence · LIVE</div><h1>Know what the market may need <span>next.</span></h1><p>The forecast engine continuously recalculates demand movement from marketplace supply, recent trend momentum and seasonal weighting. The number changes as the market signal updates.</p><div class="hero-actions"><a class="btn" href="#${privatePage?(state.user.role==='farmer'?'dashboard/listings':'marketplace'):'register'}">${privatePage?(state.user.role==='farmer'?'Act on forecast →':'Plan procurement →'):'Use AI for my business →'}</a><a class="btn outline" href="#marketplace">Explore live listings</a></div></div><div class="ai-orbit"><div class="orbit-ring ring-a"></div><div class="orbit-ring ring-b"></div><div class="orbit-core">✦<small>AI</small></div><span class="orbit-chip chip-a">Demand ↑</span><span class="orbit-chip chip-b">Momentum ↗</span><span class="orbit-chip chip-c">Supply ↻</span></div></section><section class="panel" id="forecast-panel"><div class="panel-head"><div><div class="eyebrow">Live forecast engine</div><h2>Demand monitor</h2><p class="muted" style="margin:4px 0 0">Updating automatically · <span id="forecast-updated">just now</span></p></div><span class="pill"><i class="live-dot"></i> LIVE</span></div><div class="forecast-controls">${crops.map(p=>`<button class="crop-chip ${state.forecast===p.id?'active':''}" data-forecast="${p.id}">${p.icon} ${esc(p.name)}</button>`).join('')}</div><div class="forecast-live"><div class="forecast-kpi"><span class="live-dot"></span><div><div class="forecast-number" id="forecast-number">+${forecastValue(state.forecast)}%</div><div class="forecast-label">projected demand over the next 7 days</div></div></div><div class="pill">Confidence <b id="forecast-confidence">${confidence(state.forecast)}%</b></div></div><div class="forecast-chart" id="forecast-chart">${chartBars(state.forecast)}</div><div class="forecast-summary" id="forecast-summary">${summary(state.forecast)}</div></section><div class="ai-use-grid"><article class="ai-use"><span>01 · FARMERS</span><h3>Know what to list.</h3><p>When the signal rises, farmers can time listings and quantities with more confidence.</p><a href="#${privatePage&&state.user.role==='farmer'?'dashboard/listings':'register'}">Start selling smarter →</a></article><article class="ai-use"><span>02 · BUYERS</span><h3>Know when to source.</h3><p>Spot rising demand before procurement decisions are locked in.</p><a href="#${privatePage&&state.user.role==='buyer'?'marketplace':'register'}">Plan procurement →</a></article><article class="ai-use"><span>03 · MARKETPLACE</span><h3>See the signal beside supply.</h3><p>Every listing carries a live demand indicator so intelligence stays in the buying flow.</p><a href="#marketplace">Browse with signals →</a></article></div>`}
function forecastBase(id){return crops.find(p=>p.id===id)||crops[0]}
function forecastValue(id){const p=forecastBase(id);return Math.max(3,Math.min(25,liveTrend(p)+Math.round(Math.sin(Date.now()/2100)*.8)))}
function confidence(id){const p=forecastBase(id);return Math.round(78+Math.abs(Math.sin(Date.now()/7000+p.id.length))*17)}
function chartValues(id){const p=forecastBase(id),base=forecastValue(id);return [base-3,base-1,base+2,base-2,base+4,base+1,base+5].map((x,i)=>Math.max(2,Math.round(x+Math.sin(Date.now()/4000+i)*1.2)))}
function chartBars(id){const vals=chartValues(id),max=Math.max(...vals)+3;return vals.map((v,i)=>`<div class="chart-bar" style="height:${Math.round(v/max*190)+25}px"><span>+${v}%</span><small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</small></div>`).join('')}
function summary(id){const p=forecastBase(id),v=forecastValue(id);return `<div><small>7-day forecast</small><b>+${v}%</b></div><div><small>Confidence</small><b>${confidence(id)}%</b></div><div><small>Supply pressure</small><b>${v>=12?'Tightening':v>=8?'Balanced':'Comfortable'}</b></div><div><small>AI action</small><b>${v>=12?'Consider listing early':'Monitor movement'}</b></div>`}

const FAQS={
 'listing':{title:'How do I create a listing?',body:'Farmers can publish produce directly from their workspace. Open My Listings → Create listing, enter the produce, price, available quantity, quality and location, then publish. The listing becomes visible in the marketplace immediately on this device.',action:'dashboard/listings',actionLabel:'Open My Listings'},
 'order':{title:'How do I place a bulk order?',body:'Bulk buyers can browse the Marketplace, open any available listing, choose Buy, enter the required quantity and delivery location, and place the order. A unique order code and tracking ID are created immediately.',action:'marketplace',actionLabel:'Open Marketplace'},
 'tracking':{title:'Where can I find my tracking ID?',body:'After a buyer places an order, Krishi Setu generates a unique tracking ID such as KST-XXXXXXX. Buyers can find it under Orders, farmers can find it under Logistics & Tracking, and the public Track Order page accepts that exact code.',action:'track',actionLabel:'Track an order'},
 'forecast':{title:'How does AI demand forecasting work?',body:'Krishi Setu combines the current demo market signal, crop trend and short-term movement into a rolling 7-day demand outlook. The forecast is intentionally presented beside marketplace and workspace decisions so users do not need to leave their workflow.',action:'ai',actionLabel:'Explore AI Forecast'}
};
function faqModal(key){const f=FAQS[key]||FAQS.forecast;return `<div class="modal-backdrop faq-backdrop" data-close-modal><div class="modal faq-modal"><div class="modal-head"><div><div class="eyebrow">Krishi Setu help</div><h2>${esc(f.title)}</h2></div><button class="icon-btn" data-close-modal aria-label="Close">×</button></div><div class="faq-answer"><span class="faq-answer-icon">✓</span><p>${esc(f.body)}</p></div><div class="faq-modal-actions"><button class="btn" data-faq-action="${esc(f.action)}">${esc(f.actionLabel)} →</button><button class="btn outline" data-close-modal>Close</button></div></div></div>`}
function supportPage(privatePage=false){const tickets=privatePage?read(KEY.tickets,[]).filter(t=>t.userId===state.user.id):[];const questions=[['listing','How do I create a listing?'],['order','How do I place a bulk order?'],['tracking','Where can I find my tracking ID?'],['forecast','How does AI demand forecasting work?']];const body=`<div class="support-grid"><section class="panel"><div class="panel-head"><div><div class="eyebrow">Help desk</div><h2>Send us a message</h2></div><span class="support-status"><i></i> Team online</span></div><form id="support-form"><div class="field"><label>Subject</label><input required class="input" name="subject" placeholder="What do you need help with?"></div>${privatePage?'':`<div class="field"><label>Email</label><input required type="email" class="input" name="email" placeholder="you@example.com"></div>`}<div class="field"><label>Message</label><textarea required name="message" placeholder="Describe the issue or question..."></textarea></div><button class="btn">Submit ticket →</button><div id="support-error" class="form-error"></div></form>${privatePage&&tickets.length?`<div class="support-list"><div class="eyebrow">Your tickets</div>${tickets.slice().reverse().map(t=>`<div class="ticket"><b>${esc(t.subject)}</b><small>${esc(t.status)} · ${esc(t.createdAt.slice(0,10))}</small></div>`).join('')}</div>`:''}</section><section class="panel"><div class="panel-head"><div><div class="eyebrow">Instant guidance</div><h2>Common questions</h2></div><span class="support-status">Answers here · no detour</span></div>${questions.map(([key,q])=>`<button type="button" class="quick-action" data-faq="${key}"><span class="quick-icon">?</span><span><b>${q}</b><small>Open answer</small></span><span>→</span></button>`).join('')}</section></div>`;return privatePage?dashboardShell('dashboard/support',`<div class="subpage-title"><div><div class="eyebrow">Private account support</div><h1>Support</h1><p>Tickets submitted here are attached only to your account.</p></div></div>${body}`):`${publicHeader('support')}<main class="page route-enter"><div class="container"><div class="page-top"><div><div class="eyebrow">We are here to help</div><h1>Support without the detour.</h1><p>Get an answer instantly or send a support ticket without entering a dashboard.</p></div></div>${body}</div></main>${footer()}`}
function trackPage(){return `${publicHeader('track')}<main class="page route-enter"><div class="container narrow"><div class="page-top"><div><div class="eyebrow">Public shipment lookup</div><h1>Track your order</h1><p>Nothing is shown until an exact tracking code is entered. This page never displays a list of other people's shipments.</p></div></div><section class="panel track-search"><form id="track-form"><label for="tracking-id">Tracking ID</label><div class="track-input-row"><input id="tracking-id" class="input" required placeholder="e.g. KST-AB12CD34" autocomplete="off"><button class="btn">Track shipment</button></div></form><div id="track-result" class="track-result"></div></section></div></main>${footer()}`}
function profilePage(){return dashboardShell('dashboard/profile',`<div class="subpage-title"><div><div class="eyebrow">Your account</div><h1>Profile</h1><p>Update the details used across your workspace.</p></div></div><section class="panel"><form id="profile-form"><div class="form-row"><div class="field"><label>Name</label><input class="input" name="name" value="${esc(state.user.name)}" required></div><div class="field"><label>Email</label><input class="input" value="${esc(state.user.email)}" disabled></div></div><div class="field"><label>Location</label><input class="input" name="location" value="${esc(state.user.location||'')}" required></div><button class="btn">Save profile</button><div id="profile-error" class="form-error"></div></form></section>`)}
function notFound(){return `${publicHeader()}<main class="page route-enter"><div class="container narrow"><section class="panel empty"><span class="empty-icon">⌁</span><h1>Page not found</h1><p>The page you requested does not exist.</p><a class="btn" href="#home">Back home</a></section></div></main>${footer()}`}
function listingModal(){return `<div class="modal-backdrop" data-close-modal><div class="modal"><div class="modal-head"><div><div class="eyebrow">Farmer tools</div><h2>Create a listing</h2></div><button class="icon-btn" data-close-modal>×</button></div><form id="listing-form"><div class="form-row"><div class="field"><label>Produce</label><input class="input" name="name" required placeholder="Tomatoes"></div><div class="field"><label>Price / kg</label><input class="input" name="price" required type="number" min="1" step="1" placeholder="24"></div></div><div class="form-row"><div class="field"><label>Quantity (kg)</label><input class="input" name="quantityKg" required type="number" min="1" step="1" placeholder="5000"></div><div class="field"><label>Location</label><input class="input" name="location" required value="${esc(state.user.location||'')}" placeholder="Nashik, Maharashtra"></div></div><div class="field"><label>Quality</label><select class="select" name="grade"><option>Grade A</option><option>Premium</option><option>Export</option><option>Fresh</option></select></div><button class="btn full">Publish listing →</button><div id="modal-error" class="form-error"></div></form></div></div>`}
function orderModal(p){return `<div class="modal-backdrop" data-close-modal><div class="modal"><div class="modal-head"><div><div class="eyebrow">Bulk procurement</div><h2>Order ${esc(p.name)}</h2></div><button class="icon-btn" data-close-modal>×</button></div>${forecastPill(p)}<div class="notice">${qty(p.quantityKg)} available at ${money(p.price)}/kg.</div><form id="order-form" data-listing="${esc(p.id)}"><div class="field"><label>Quantity (kg)</label><input class="input" name="quantityKg" required type="number" min="1" max="${p.quantityKg}" value="${Math.min(1000,p.quantityKg)}"></div><div class="field"><label>Delivery location</label><input class="input" name="destination" required placeholder="FreshMart DC, Mumbai"></div><button class="btn full">Place order securely →</button><div id="modal-error" class="form-error"></div></form></div></div>`}
function openModal(html){$('#modal-root').innerHTML=html;document.body.classList.add('modal-open');bindModalUI();bindModalForms();}
function bindModalUI(){
 const root=$('#modal-root');
 root?.querySelectorAll('[data-close-modal]').forEach(el=>el.onclick=e=>{if(e.currentTarget===e.target||e.currentTarget.classList.contains('icon-btn')||e.currentTarget.hasAttribute('data-close-modal')&&e.target.closest('.icon-btn'))closeModal()});
 root?.querySelectorAll('[data-faq-action]').forEach(b=>b.onclick=()=>{const target=b.dataset.faqAction;closeModal();go(target)});
}
function bindModalForms(){
 const lf=$('#listing-form');
 if(lf&&!lf.dataset.bound){lf.dataset.bound='1';lf.onsubmit=e=>{e.preventDefault();const fd=new FormData(lf);const name=String(fd.get('name')).trim();const price=Number(fd.get('price')),q=Number(fd.get('quantityKg')),location=String(fd.get('location')).trim();const base=crops.find(c=>c.name.toLowerCase()===name.toLowerCase());if(!name||price<=0||q<=0||!location){$('#modal-error').textContent='Complete all listing fields with valid values.';return}state.listings.push({id:uid(),name,icon:base?.icon||'🌱',tone:base?.tone||'leaf',grade:String(fd.get('grade')),price,quantityKg:q,location,farmer:state.user.name,farmerId:state.user.id,baseTrend:base?.baseTrend||6,isSeed:false,createdAt:new Date().toISOString()});write(KEY.listings,state.listings);closeModal();toast('Listing published to the marketplace.');render()}}
 const of=$('#order-form');
 if(of&&!of.dataset.bound){of.dataset.bound='1';of.onsubmit=e=>{e.preventDefault();try{const p=state.listings.find(x=>x.id===of.dataset.listing);if(!p)throw Error('This listing is no longer available.');const fd=new FormData(of);const o=createOrder(p,Number(fd.get('quantityKg')),String(fd.get('destination')).trim());closeModal();toast(`Order ${o.orderCode} placed. Tracking ${o.trackingId}`);go('dashboard/orders')}catch(err){const m=$('#modal-error');if(m)m.textContent=err.message}}}
}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('modal-open')}

/* Password hashing without external dependencies. WebCrypto is available on modern browsers; a deterministic fallback is kept for older/file:// environments. */
async function hashPassword(s){try{if(crypto.subtle){const data=new TextEncoder().encode(s);const buf=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,'0')).join('')}}catch{}let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return 'fallback-'+(h>>>0).toString(16)}

function createOrder(p,quantityKg,destination){const buyer=state.user;if(!buyer||buyer.role!=='buyer')throw Error('Sign in as a bulk buyer to place an order.');if(quantityKg<=0||quantityKg>p.quantityKg)throw Error('Enter a quantity within the available supply.');const orderCode='KS-'+Math.random().toString(36).slice(2,8).toUpperCase();const trackingId='KST-'+Math.random().toString(36).slice(2,10).toUpperCase();const now=new Date();const farmerId=p.farmerId||null;const order={id:uid(),orderCode,trackingId,crop:p.name,listingId:p.id,quantityKg,price:p.price,total:quantityKg*p.price,buyerId:buyer.id,buyerName:buyer.name,farmerId,farmerName:p.farmer||'Marketplace supplier',destination,status:'Order placed',createdAt:now.toISOString(),events:[{label:'Order placed',done:true,date:now.toLocaleDateString('en-IN')},{label:'Confirmed',done:false,date:''},{label:'Picked up',done:false,date:''},{label:'In transit',done:false,date:''},{label:'Delivered',done:false,date:''}]};state.orders.push(order);if(!p.isSeed){p.quantityKg-=quantityKg;state.listings=state.listings.map(x=>x.id===p.id?p:x);write(KEY.listings,state.listings)}write(KEY.orders,state.orders);return order}

function renderTrack(o){if(!o)return `<div class="notice error-notice"><b>Tracking ID not found.</b><br>Check the code and try again. For privacy, this page does not expose a directory of shipments.</div>`;return `<div class="tracking-result-card"><div class="tracking-head"><div><div class="eyebrow">${esc(o.trackingId)}</div><h2>${esc(o.crop)} · ${qty(o.quantityKg)}</h2><p>Destination: ${esc(o.destination)}</p></div><span class="status">${esc(o.status)}</span></div><div class="timeline">${o.events.map(e=>`<div class="timeline-step ${e.done?'done':''}"><span>${e.done?'✓':'○'}</span><b>${esc(e.label)}</b><small>${esc(e.date||'Pending')}</small></div>`).join('')}</div><div class="notice">For security, public tracking shows only shipment progress — never account email, private addresses, payment details or other orders.</div></div>`}

function bindCommon(){
 $$('.mobile-menu').forEach(b=>b.onclick=()=>{const d=$('[data-drawer]');d?.classList.toggle('open')});
 $$('[data-drawer] a').forEach(a=>a.addEventListener('click',()=> $('[data-drawer]')?.classList.remove('open')));
 $$('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;if(!state.user){toast('Sign in to save listings.','warn');go('login');return}state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];write(KEY.saved+'_'+state.user.id,state.saved);toast(state.saved.includes(id)?'Listing saved to your account.':'Listing removed from saved.');render()});
 $$('[data-order]').forEach(b=>b.onclick=()=>{if(!state.user){toast('Sign in as a bulk buyer to order.','warn');go('login');return}if(state.user.role!=='buyer'){toast('Ordering is available from a bulk buyer workspace.','warn');return}const p=state.listings.find(x=>x.id===b.dataset.order);if(p)openModal(orderModal(p))});
 $$('[data-clear-filters]').forEach(b=>b.onclick=()=>{state.marketFilter={q:'',category:'',location:'',sort:'recommended'};render()});
 $$('[data-new-listing]').forEach(b=>b.onclick=()=>{if(state.user?.role==='farmer')openModal(listingModal())});
 $$('[data-delete-listing]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteListing;const p=state.listings.find(x=>x.id===id);if(!p||p.farmerId!==state.user.id)return;if(confirm(`Remove ${p.name} from your marketplace listings?`)){state.listings=state.listings.filter(x=>x.id!==id);write(KEY.listings,state.listings);toast('Listing removed.');render()}});
 $$('[data-advance-order]').forEach(b=>b.onclick=()=>advanceOrder(b.dataset.advanceOrder));
 $$('[data-logout]').forEach(b=>b.onclick=()=>{localStorage.removeItem(KEY.session);state.user=null;state.saved=[];toast('Signed out.');go('home')});
 $$('[data-dash-menu]').forEach(b=>b.onclick=()=>{const shell=$('.app-shell'),side=$('[data-sidebar]');if(!shell||!side)return;const mobile=window.matchMedia('(max-width:760px)').matches;if(mobile){side.classList.toggle('open');b.setAttribute('aria-expanded',side.classList.contains('open')?'true':'false')}else{shell.classList.toggle('sidebar-collapsed');b.setAttribute('aria-expanded',shell.classList.contains('sidebar-collapsed')?'false':'true')}});
 $$('[data-faq]').forEach(b=>b.onclick=()=>openModal(faqModal(b.dataset.faq)));
 $$('[data-faq-action]').forEach(b=>b.onclick=()=>{const target=b.dataset.faqAction;closeModal();go(target)});
 $$('[data-close-modal]').forEach(b=>b.onclick=e=>{if(e.target===b||e.target.closest('.icon-btn'))closeModal()});
 const sf=$('#support-form');if(sf)sf.onsubmit=e=>{e.preventDefault();const fd=new FormData(sf);const tickets=read(KEY.tickets,[]);tickets.push({id:uid(),userId:state.user?.id||null,email:String(fd.get('email')||state.user?.email||''),subject:String(fd.get('subject')),message:String(fd.get('message')),status:'Open',createdAt:new Date().toISOString()});write(KEY.tickets,tickets);sf.reset();toast('Support ticket submitted successfully.');if(state.user)setTimeout(render,250)};
 const pf=$('#profile-form');if(pf)pf.onsubmit=e=>{e.preventDefault();const fd=new FormData(pf);const users=read(KEY.users,[]);const u=users.find(x=>x.id===state.user.id);u.name=String(fd.get('name')).trim();u.location=String(fd.get('location')).trim();write(KEY.users,users);state.user=u;toast('Profile updated.');render()};
 const tf=$('#track-form');if(tf)tf.onsubmit=e=>{e.preventDefault();const id=$('#tracking-id').value.trim().toUpperCase();const o=read(KEY.orders,[]).find(x=>x.trackingId.toUpperCase()===id);$('#track-result').innerHTML=renderTrack(o)};

 const af=$('#auth-form');if(af)af.onsubmit=async e=>{e.preventDefault();const err=$('#auth-error');err.textContent='';const fd=new FormData(af);const email=String(fd.get('email')).trim().toLowerCase();const password=String(fd.get('password'));try{const users=read(KEY.users,[]);if(af.dataset.kind==='register'){const name=String(fd.get('name')).trim(),location=String(fd.get('location')).trim();const role=$('.role-switch button.active')?.dataset.role||'farmer';if(!name||!email||!location)throw Error('Please complete all required fields.');if(password.length<6)throw Error('Password must be at least 6 characters.');if(users.some(u=>u.email===email))throw Error('An account with this email already exists.');const u={id:uid(),name,email,location,role,passwordHash:await hashPassword(password),createdAt:new Date().toISOString()};users.push(u);write(KEY.users,users);localStorage.setItem(KEY.session,u.id);state.user=u;state.saved=[];toast('Workspace created successfully.');go('dashboard')}else{const u=users.find(x=>x.email===email);if(!u||u.passwordHash!==await hashPassword(password))throw Error('Email or password is incorrect.');localStorage.setItem(KEY.session,u.id);state.user=u;state.saved=read(KEY.saved+'_'+u.id,[]);toast('Welcome back.');go('dashboard')}}catch(ex){err.textContent=ex.message}};
 $$('.role-switch button').forEach(b=>b.onclick=()=>{$$('.role-switch button').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
 $$('[data-password-toggle]').forEach(b=>b.onclick=()=>{const input=$('#auth-password');input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Show':'Hide'});
 $$('[data-forecast]').forEach(b=>b.onclick=()=>{state.forecast=b.dataset.forecast;updateForecastPanel()});
 bindMarket();
}
function bindMarket(){const q=$('#market-search'),c=$('#market-category'),l=$('#market-location'),s=$('#market-sort');if(!q)return;const refresh=()=>{state.marketFilter={q:q.value,category:c.value,location:l.value,sort:s.value};const grid=$('#market-grid');grid.innerHTML=filteredListings().map(card).join('')||`<div class="panel empty" style="grid-column:1/-1"><span class="empty-icon">⌁</span><h3>No matching produce</h3><p>Try a different filter.</p><button class="btn outline" data-clear-filters>Clear filters</button></div>`;bindCommon()};[q,c,l,s].forEach(x=>x.addEventListener('input',refresh));[c,l,s].forEach(x=>x.addEventListener('change',refresh))}
function updateForecastPanel(){const n=$('#forecast-number');if(!n)return;n.classList.remove('updating');void n.offsetWidth;n.classList.add('updating');n.textContent='+'+forecastValue(state.forecast)+'%';$('#forecast-confidence').textContent=confidence(state.forecast)+'%';$('#forecast-chart').innerHTML=chartBars(state.forecast);$('#forecast-summary').innerHTML=summary(state.forecast);$('#forecast-updated').textContent='just now';$$('[data-forecast]').forEach(b=>b.classList.toggle('active',b.dataset.forecast===state.forecast))}
function startLive(){clearInterval(window.__live);window.__live=setInterval(()=>{if(document.hidden)return;const r=route();if(r==='ai'||r==='dashboard/ai'){updateForecastPanel();}else if(r==='home'||r==='marketplace'||r.startsWith('product/')){$$('.forecast-pill').forEach((el,i)=>{const p=state.listings[i%state.listings.length];if(p)el.outerHTML=forecastPill(p)});$$('.demand-track b').forEach((b,i)=>{const p=crops[i%crops.length];b.textContent='↑ '+liveTrend(p)+'%'});}},2800)}
function render(){bootstrap();const r=route();let html;if(r==='home')html=home();else if(r==='marketplace')html=marketplace();else if(r==='how')html=home();else if(r==='ai')html=aiPage(false);else if(r==='track')html=trackPage();else if(r==='support')html=supportPage(false);else if(r==='login')html=authPage('login');else if(r==='register')html=authPage('register');else if(r.startsWith('product/'))html=productDetail(decodeURIComponent(r.slice(8)));else if(r.startsWith('dashboard')){if(!state.user){toast('Please sign in to enter your workspace.','warn');return go('login')}if(r==='dashboard')html=dashboard();else if(r==='dashboard/orders')html=ordersPage();else if(r==='dashboard/listings')html=listingsPage();else if(r==='dashboard/ai')html=aiPage(true);else if(r==='dashboard/logistics')html=logisticsPage();else if(r==='dashboard/support')html=supportPage(true);else if(r==='dashboard/profile')html=profilePage();else html=notFound()}else html=notFound();$('#app').innerHTML=html;bindCommon();if(r==='ai'||r==='dashboard/ai')updateForecastPanel();startLive();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',render);window.addEventListener('DOMContentLoaded',()=>{bootstrap();render()});
